13\\\\t            instance=ServiceDependencies(\\\\n   114\\\\t                config=daemon.config,\\\\n   115\\\\t                git=daemon.git_service,\\\\n   116\\\\t                index=daemon.index_service,\\\\n   117\\\\t                gitstatusd=daemon.gitstatusd_service,\\\\n   118\\\\t                prs=daemon.pr_provider,\\\\n   119\\\\t                status=daemon.status_service,\\\\n   120\\\\t                discovery=daemon.discovery_service,\\\\n   121\\\\t                health=daemon.health_service,\\\\n   122\\\\t                coordinator=daemon.coordinator,\\\\n   123\\\\t            ),\\\\n   124\\\\t        )\\\\n   125\\\\t        args = []\\\\n   126\\\\t        type_hints = get_type_hints(fn)\\\\n   127\\\\t        for p in sig.parameters.values():\\\\n   128\\\\t            anno = type_hints.get(p.name, p.annotation)\\\\n   129\\\\t            if stream_obj is not None and (anno is Stream or get_origin(anno) is Stream):\\\\n   130\\\\t                args.append(stream_obj)\\\\n   131\\\\t            elif params_obj is not None and anno is type(params_obj):\\\\n   132\\\\t                args.append(params_obj)\\\\n   133\\\\t\\\\n   134\\\\t            else:\\\\n   135\\\\t                args.append(c.resolve(anno))\\\\n   136\\\\t        return args\\\\n   137\\\\t\\\\n   138\\\\t    def _wrap_method[ParamsT: BaseModel](self, method: str, params_model: type[ParamsT] | None, handler) -> None:\\\\n   139\\\\t        async def _wrapped(req: Request, daemon: WtDaemon, writer, start_time: datetime) -> Response | ErrorResponse:\\\\n   140\\\\t            try:\\\\n   141\\\\t                params = params_model.model_validate(req.params) if params_model is not None else None\\\\n   142\\\\t            except ValidationError as e:\\\\n   143\\\\t                return create_error_response(ErrorCodes.INVALID_PARAMS, str(e), req.id)\\\\n   144\\\\t\\\\n   145\\\\t            try:\\\\n   146\\\\t                args = self._build_args(\\\